import{_ as e,o as r,c as i,a0 as a}from"./chunks/framework.DJ-9CPBN.js";const o="/Auditerra-Technical-Documentation-/assets/sad.BQddX53L.png",s="/Auditerra-Technical-Documentation-/assets/figma.BRdIzFYK.png",m=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md"}'),n={name:"architecture/overview.md"};function d(l,t,c,g,u,p){return r(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>Auditerra is built on three core principles:</p><ol><li><strong>Offline First:</strong> Field operations work in zero connectivity zones.</li><li><strong>Verified by field agronomists:</strong> Replace satellite guesses with on-the-ground data.</li><li><strong>Audit Ready:</strong> Every action is traceable and verifiable.</li></ol><hr><h2 id="system-architecture" tabindex="-1">System Architecture <a class="header-anchor" href="#system-architecture" aria-label="Permalink to &quot;System Architecture&quot;">​</a></h2><p>The system follows a layered architecture that separates external user interfaces, application logic, data processing, and storage. This design ensures scalability, maintainability, and clear separation of concerns.</p><h3 id="architecture-layers" tabindex="-1">Architecture Layers <a class="header-anchor" href="#architecture-layers" aria-label="Permalink to &quot;Architecture Layers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Components</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>Presentation</strong></td><td>USSD Interface, Expert PWA, Supervisor Dashboard</td><td>User interaction and data collection</td></tr><tr><td><strong>Application</strong></td><td>Matching Service, AI Module, Verification Module</td><td>Business logic and orchestration</td></tr><tr><td><strong>Data</strong></td><td>PostgreSQL, IndexedDB, Redis</td><td>Persistent storage and caching</td></tr><tr><td><strong>Integration</strong></td><td>Africa&#39;s Talking, SMS Leopard, Gemini API</td><td>External service communication</td></tr></tbody></table><h3 id="system-architecture-diagram" tabindex="-1">System Architecture Diagram <a class="header-anchor" href="#system-architecture-diagram" aria-label="Permalink to &quot;System Architecture Diagram&quot;">​</a></h3><p><img src="'+o+'" alt="System Architecture Preview"></p><blockquote><p><em>This diagram shows the end-to-end system architecture including all components, data flows, and external integrations.</em></p></blockquote><p><strong>Reference Diagram:</strong> <a href="https://lucid.app/lucidspark/4f756537-28a5-4ec6-93b5-b11e2f710a06/edit?viewport_loc=-54%2C-300%2C5760%2C3258%2C0_0&amp;invitationId=inv_b287c0c7-94d1-48cf-9f38-08a14172df1b" target="_blank" rel="noreferrer">View the Lucidchart Architecture Diagram</a></p><hr><h2 id="component-breakdown" tabindex="-1">Component Breakdown <a class="header-anchor" href="#component-breakdown" aria-label="Permalink to &quot;Component Breakdown&quot;">​</a></h2><h3 id="_1-farmers-and-ussd-interface" tabindex="-1">1. Farmers and USSD Interface <a class="header-anchor" href="#_1-farmers-and-ussd-interface" aria-label="Permalink to &quot;1. Farmers and USSD Interface&quot;">​</a></h3><p><strong>Purpose:</strong> Allow smallholder farmers to report soil and agricultural issues using basic feature phones.</p><p><strong>How It Works:</strong> Farmers dial the USSD shortcode (<code>*384*55#</code>) from any basic feature phone. The system guides them through a structured menu:</p><ul><li>Registration: Collects name, ID, phone number, county, sub-county, and landmark</li><li>Issue Reporting: Captures category (Soil, Water, Crop, Erosion) and severity (Mild, Moderate, High)</li><li>Confirmation: Generates a unique 4-digit handshake code and sends an SMS confirmation</li></ul><p><strong>Technology:</strong> Africa&#39;s Talking USSD API</p><p><strong>Security Considerations:</strong></p><ul><li>Numeric inputs only to prevent injection attacks</li><li>30-second session timeout to free up resources</li><li>Phone numbers normalized to E.164 format</li><li>All USSD interactions logged for audit purposes</li></ul><p><strong>Limitations Addressed:</strong></p><ul><li>Works on 2G networks with no internet required</li><li>Handles feature phones with minimal processing power</li><li>Menu structure compressed to fit within 30-second session windows</li></ul><hr><h3 id="_2-reporting-module" tabindex="-1">2. Reporting Module <a class="header-anchor" href="#_2-reporting-module" aria-label="Permalink to &quot;2. Reporting Module&quot;">​</a></h3><p><strong>Purpose:</strong> Convert farmer USSD inputs into structured service tickets for processing.</p><p><strong>How It Works:</strong> The module receives the issue category and severity from the USSD interface, creates an immutable ticket record with a UUID, and triggers the expert matching process. Each ticket is assigned a unique 4-digit handshake code that serves as the security verification token.</p><p><strong>Ticket States:</strong></p><table tabindex="0"><thead><tr><th>State</th><th>Description</th></tr></thead><tbody><tr><td><strong>PENDING</strong></td><td>Ticket created, awaiting expert assignment</td></tr><tr><td><strong>MATCHED</strong></td><td>Expert found, awaiting acceptance</td></tr><tr><td><strong>DISPATCHED</strong></td><td>Expert notified and traveling</td></tr><tr><td><strong>ON_SITE</strong></td><td>Expert at farm, handshake complete</td></tr><tr><td><strong>RESOLVED</strong></td><td>Issue addressed, awaiting final verification</td></tr><tr><td><strong>COMPLETED</strong></td><td>60-day retest confirms restoration</td></tr><tr><td><strong>CANCELLED</strong></td><td>Ticket cancelled by farmer or system</td></tr></tbody></table><p><strong>Data Collected:</strong></p><ul><li>Farmer identification (name, phone, location)</li><li>Issue category and sub-category</li><li>Severity level</li><li>Timestamp and geographic coordinates</li><li>Unique handshake code (hashed)</li></ul><hr><h3 id="_3-matching-service" tabindex="-1">3. Matching Service <a class="header-anchor" href="#_3-matching-service" aria-label="Permalink to &quot;3. Matching Service&quot;">​</a></h3><p><strong>Purpose:</strong> Find the most suitable field expert for each farmer&#39;s issue using a multi-factor scoring system.</p><p><strong>How It Works:</strong> The matching engine evaluates available experts using a weighted scoring matrix and ranks them to find the optimal match.</p><p><strong>Scoring Matrix:</strong></p><table tabindex="0"><thead><tr><th>Factor</th><th>Weight</th><th>Calculation</th></tr></thead><tbody><tr><td><strong>Proximity</strong></td><td>40%</td><td>PostGIS spatial query within 15km radius</td></tr><tr><td><strong>Technical Specialization</strong></td><td>35%</td><td>Match between expert skills and issue category</td></tr><tr><td><strong>Language Compatibility</strong></td><td>15%</td><td>Match between farmer&#39;s preferred language and expert&#39;s languages</td></tr><tr><td><strong>Availability</strong></td><td>10%</td><td>Current workload and acceptance rate</td></tr></tbody></table><p><strong>Dynamic Radius Expansion:</strong> The system automatically expands the search radius if no expert is found:</p><ul><li>Attempt 1: 15km</li><li>Attempt 2: 30km</li><li>Attempt 3: 45km</li><li>Attempt 4: Unlimited (nationwide)</li></ul><p><strong>Match Confirmation:</strong></p><ul><li><strong>Farmer:</strong> Receives SMS with expert name and estimated arrival time</li><li><strong>Expert:</strong> Receives web push notification with ticket details and farmer location</li><li><strong>Supervisor:</strong> Dashboard updates to show MATCHED status</li></ul><hr><h3 id="_4-syncing-module" tabindex="-1">4. Syncing Module <a class="header-anchor" href="#_4-syncing-module" aria-label="Permalink to &quot;4. Syncing Module&quot;">​</a></h3><p><strong>Purpose:</strong> Enable offline-first field operations for experts working in areas without connectivity.</p><p><strong>How It Works:</strong> The expert PWA stores operational data locally using <strong>IndexedDB</strong>. The <strong>Service Worker</strong> intercepts network requests and manages caching. The <strong>Background Sync API</strong> detects when connectivity is restored and automatically uploads queued data.</p><p><strong>Offline Storage Architecture:</strong></p><p><strong>Data Cached Offline:</strong></p><ul><li>Tickets: Up to 10 days of assignments</li><li>Diagnostic forms: Complete forms awaiting sync</li><li>Location data: GPS coordinates and farm boundaries</li><li>Photos: Compressed field images</li></ul><p><strong>Security:</strong></p><ul><li>Highly Restricted data is not cached</li><li>JWT tokens expire after 1 hour</li><li>Cache is cleared on logout</li><li>Data encrypted at rest in IndexedDB</li></ul><hr><h3 id="_5-location-module" tabindex="-1">5. Location Module <a class="header-anchor" href="#_5-location-module" aria-label="Permalink to &quot;5. Location Module&quot;">​</a></h3><p><strong>Purpose:</strong> Capture and manage geospatial data for farm visits, enabling accurate boundary mapping and spatial analysis.</p><p><strong>How It Works:</strong> The expert&#39;s device captures GPS coordinates via the W3C Geolocation API. The backend stores these coordinates in PostgreSQL with PostGIS extension, allowing farm boundaries to be represented as spatial polygons.</p><p><strong>Spatial Data Types:</strong></p><ul><li>Point: Single GPS coordinate (expert location, farm centroid)</li><li>Polygon: Farm boundary mapped by walking the perimeter</li><li>Linestring: Road or path tracking</li><li>Multipolygon: Multiple plots for a single farmer</li></ul><p><strong>PostGIS Functionality:</strong></p><ul><li>Distance calculations for proximity matching</li><li>Spatial joins for region analysis</li><li>Geospatial aggregation for dashboard metrics</li><li>Boundary overlap detection to prevent duplicate registrations</li></ul><p><strong>Data Flow:</strong></p><ol><li>Expert walks farm perimeter while device drops GPS pins</li><li>PWA calculates geometric polygon from coordinate stream</li><li>Polygon stored locally in IndexedDB (offline)</li><li>Background sync uploads polygon to cloud</li><li>PostGIS processes polygon for spatial queries</li><li>Dashboard renders farm boundaries on interactive map</li></ol><hr><h3 id="_6-verification-module" tabindex="-1">6. Verification Module <a class="header-anchor" href="#_6-verification-module" aria-label="Permalink to &quot;6. Verification Module&quot;">​</a></h3><p><strong>Purpose:</strong> Verify that field visits actually occurred and track restoration progress over time.</p><p><strong>How It Works:</strong> The module uses a 4-digit Security Handshake code to prove physical presence at the farm location. This prevents fraud and ensures data integrity.</p><p><strong>Code Management:</strong></p><ul><li>Generated via <code>crypto.randomInt()</code> for true randomness</li><li>Hashed with bcrypt before storage (preventing database exposure)</li><li>Sent to farmer via SMS with instruction: &quot;Do not share until expert arrives&quot;</li><li>Expires after 24 hours to prevent reuse</li><li>Failed attempts limited to 5 before lockout</li></ul><p><strong>60-Day Audit Loop:</strong> After the initial visit, the system automatically schedules a 60-day retest. The expert must return to the same farm, perform the same measurements, and log the results. This enforces measurement of biological survival rather than just planting speed.</p><p><strong>Verification Metrics Tracked:</strong></p><ul><li>Soil pH change</li><li>Nitrogen, Phosphorus, Potassium levels</li><li>Crop yield data</li><li>Farmer satisfaction rating</li><li>Photo evidence of restoration</li></ul><hr><h3 id="_7-ai-module" tabindex="-1">7. AI Module <a class="header-anchor" href="#_7-ai-module" aria-label="Permalink to &quot;7. AI Module&quot;">​</a></h3><p><strong>Purpose:</strong> Generate agronomic recommendations using Retrieval-Augmented Generation (RAG) with Google Gemini.</p><p><strong>How It Works:</strong> The AI module uses Retrieval-Augmented Generation to ground recommendations in authoritative agricultural science.</p><p><strong>RAG Process Flow:</strong></p><p><strong>Knowledge Base:</strong></p><ul><li>Project-specific Markdown files uploaded to Gemini File Search store</li><li>KALRO (Kenya Agricultural and Livestock Research Organization) guidelines</li><li>ICRAF (World Agroforestry) best practices</li><li>Peer-reviewed agricultural research</li><li>Localized agronomic data</li></ul><p><strong>Prompt Engineering:</strong></p><ol><li><strong>Anonymization:</strong> Farmer identity removed before AI processing</li><li><strong>Context Construction:</strong> Soil parameters structured with field data</li><li><strong>Constraint Setting:</strong> Response format and length restrictions</li><li><strong>Citation Requirement:</strong> AI must reference source documents</li></ol><p><strong>Output Streams:</strong></p><table tabindex="0"><thead><tr><th>Stream</th><th>Format</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Farmer SMS</strong></td><td>160 characters max</td><td>Actionable steps only</td></tr><tr><td><strong>Expert Brief</strong></td><td>Full report</td><td>Detailed scientific rationale</td></tr><tr><td><strong>Institutional Data</strong></td><td>Dashboard metrics</td><td>Aggregated for oversight</td></tr></tbody></table><p><strong>Security:</strong></p><ul><li>Farmer identity removed before AI requests</li><li>Outputs constrained to prevent harmful recommendations</li><li>Input/output hashes maintained for audit purposes</li><li>RAG ensures responses are grounded in verified sources</li></ul><hr><h3 id="_8-sms-alert-module" tabindex="-1">8. SMS Alert Module <a class="header-anchor" href="#_8-sms-alert-module" aria-label="Permalink to &quot;8. SMS Alert Module&quot;">​</a></h3><p><strong>Purpose:</strong> Deliver prescriptions, verification codes, and operational notifications to all users.</p><p><strong>How It Works:</strong> The module uses a primary SMS gateway with automatic failover to ensure delivery.</p><p><strong>SMS Architecture:</strong></p><table tabindex="0"><thead><tr><th>Component</th><th>Technology</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Primary Gateway</strong></td><td>Africa&#39;s Talking</td><td>USSD and primary SMS delivery</td></tr><tr><td><strong>Secondary Gateway</strong></td><td>SMS Leopard</td><td>Automatic failover for SMS</td></tr><tr><td><strong>Retry Policy</strong></td><td>3 attempts, exponential backoff</td><td>Ensure message delivery</td></tr><tr><td><strong>Rate Limiting</strong></td><td>10/day (farmers), 100/day (experts)</td><td>Prevent abuse</td></tr></tbody></table><p><strong>Message Types:</strong></p><ul><li>Registration confirmation</li><li>Handshake code delivery</li><li>Expert dispatch notification</li><li>AI-generated prescription</li><li>60-day retest reminder</li><li>Operational alerts and status updates</li></ul><p><strong>Security:</strong></p><ul><li>API keys stored in Secret Manager (not in code)</li><li>Rate limiting per user (10/day farmers, 100/day experts)</li><li>Passwords and GPS coordinates never included in SMS</li><li>No personally identifiable information in messages</li><li>All SMS interactions logged for audit</li></ul><p><strong>Deliverability:</strong></p><ul><li>Phone numbers normalized to E.164 format</li><li>Multiple retry attempts for failed messages</li><li>SMS content compressed to 160 characters</li><li>Unicode support for Kiswahili messages</li></ul><hr><h3 id="_9-supervisor-dashboard" tabindex="-1">9. Supervisor Dashboard <a class="header-anchor" href="#_9-supervisor-dashboard" aria-label="Permalink to &quot;9. Supervisor Dashboard&quot;">​</a></h3><p><strong>Purpose:</strong> Provide institutional supervisors with operational oversight and comprehensive audit capabilities.</p><p><strong>Features:</strong></p><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Interactive National Map</strong></td><td>Visual representation of all active restoration sites</td></tr><tr><td><strong>Real-Time Ticket Tracking</strong></td><td>Live status updates for all tickets</td></tr><tr><td><strong>Expert Deployment Density</strong></td><td>Heatmap showing expert coverage</td></tr><tr><td><strong>60-Day Audit Reminders</strong></td><td>Automated alerts for upcoming retests</td></tr><tr><td><strong>Exportable Impact Reports</strong></td><td>PDF and CSV exports for funders</td></tr><tr><td><strong>Aggregated Statistics</strong></td><td>Key metrics and performance indicators</td></tr></tbody></table><p><strong>Dashboard Layout:</strong></p><ol><li><strong>Top Navigation:</strong> Title and user actions</li><li><strong>Stat Cards:</strong> Key metrics (hectares restored, active sites, expert count)</li><li><strong>Interactive Map:</strong> Region map with site markers</li><li><strong>Charts:</strong> Restoration progress visualizations</li><li><strong>Data Table:</strong> Regional restoration matrix with export</li></ol><p><strong>Data Sources:</strong></p><ul><li>Tickets: Active and historical</li><li>Locations: GPS polygons and site status</li><li>Experts: Deployment and availability</li><li>Diagnostics: Soil health metrics</li><li>Audit Compliance: 60-day retest completion</li></ul><p><strong>Audit Reports:</strong></p><ul><li>Immutable proof-of-impact for global climate funders</li><li>Exportable in multiple formats (PDF, CSV, JSON)</li><li>Timestamped and verifiable</li><li>Includes photographic evidence</li><li>Tracks both initial visit and 60-day retest results</li></ul><hr><h2 id="data-flow-and-system-integration" tabindex="-1">Data Flow and System Integration <a class="header-anchor" href="#data-flow-and-system-integration" aria-label="Permalink to &quot;Data Flow and System Integration&quot;">​</a></h2><p>The architecture follows a strict, secure data path for every transaction.</p><p><strong>Step 1: Report</strong></p><ul><li>Farmer dials <code>*384*55#</code> → USSD menu</li><li>Issue category and severity submitted</li><li>4-digit handshake code generated</li><li>SMS confirmation sent to farmer</li><li>Ticket status: <strong>PENDING</strong></li></ul><p><strong>Step 2: Match</strong></p><ul><li>Backend uses PostGIS for proximity query</li><li>Multi-factor scoring evaluates available experts</li><li>Best expert selected and notified</li><li>Status: <strong>MATCHED</strong></li></ul><p><strong>Step 3: Verify</strong></p><ul><li>Expert travels to farm location</li><li>Device captures GPS coordinates</li><li>Handshake code entered and verified</li><li>Status: <strong>ON_SITE</strong></li></ul><p><strong>Step 4: Diagnose</strong></p><ul><li>Expert logs soil parameters (pH, N, P, K)</li><li>Photos captured and stored locally</li><li>Data stored in IndexedDB (offline)</li><li>Background sync when connectivity returns</li></ul><p><strong>Step 5: Prescribe</strong></p><ul><li>Data synced to cloud</li><li>AI generates recommendation using RAG</li><li>Output delivered: Farmer SMS, Expert Brief, Dashboard update</li><li>60-day retest scheduled</li><li>Status: <strong>RESOLVED</strong></li></ul><p><strong>Step 6: Audit (60-Day Retest)</strong></p><ul><li>Expert returns to farm location</li><li>Repeat diagnostic measurements</li><li>Data compared to baseline</li><li>Restoration verified or re-intervention scheduled</li><li>Status: <strong>COMPLETED</strong></li></ul><hr><h2 id="design-brand-guidelines" tabindex="-1">Design &amp; Brand Guidelines <a class="header-anchor" href="#design-brand-guidelines" aria-label="Permalink to &quot;Design &amp; Brand Guidelines&quot;">​</a></h2><p>The Auditerra interface is designed for readability and clarity, specifically optimized for mobile devices and low-bandwidth environments.</p><h3 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Principle</th><th>Application</th></tr></thead><tbody><tr><td><strong>Low Connectivity Focus</strong></td><td>Mobile-first design, fast loading on 2G networks, offline functionality</td></tr><tr><td><strong>Simple and Clear</strong></td><td>Heavy icon usage to bypass language barriers, color coding for status</td></tr><tr><td><strong>Accessibility</strong></td><td>High contrast ratios for outdoor field conditions, readable fonts</td></tr><tr><td><strong>Trustworthy</strong></td><td>Professional agricultural aesthetic, consistent visual language</td></tr></tbody></table><h3 id="color-palette" tabindex="-1">Color Palette <a class="header-anchor" href="#color-palette" aria-label="Permalink to &quot;Color Palette&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Color</th><th>Hex</th><th>Usage</th></tr></thead><tbody><tr><td><strong>Primary Dark</strong></td><td>Brown</td><td><code>#5B3D26</code></td><td>Headings, navigation, major UI elements</td></tr><tr><td><strong>Primary Light</strong></td><td>White</td><td><code>#FFFFFF</code></td><td>Backgrounds, text on dark surfaces</td></tr><tr><td><strong>Secondary</strong></td><td>Green</td><td><code>#4C8A42</code></td><td>Buttons, success states, CTAs</td></tr><tr><td><strong>Accent</strong></td><td>Teal</td><td><code>#436A4B</code></td><td>Accent elements, highlights</td></tr><tr><td><strong>Background</strong></td><td>Off-white</td><td><code>#F9FBF9</code></td><td>Page backgrounds</td></tr><tr><td><strong>Success</strong></td><td>Light Green</td><td><code>#E8F5E9</code></td><td>Success indicators</td></tr><tr><td><strong>Warning</strong></td><td>Amber</td><td><code>#F59E0B</code></td><td>Pending status, warnings</td></tr><tr><td><strong>Error</strong></td><td>Red</td><td><code>#DC2626</code></td><td>Errors, critical issues</td></tr></tbody></table><h3 id="typography" tabindex="-1">Typography <a class="header-anchor" href="#typography" aria-label="Permalink to &quot;Typography&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Specification</th><th>Usage</th></tr></thead><tbody><tr><td><strong>Primary Font</strong></td><td>Fira Sans</td><td>All text content</td></tr><tr><td><strong>Weights</strong></td><td>Regular (400), Medium (500), Bold (700)</td><td>Typographic hierarchy</td></tr><tr><td><strong>Headings</strong></td><td>Bold, 1.2+ line-height</td><td>Section titles</td></tr><tr><td><strong>Body</strong></td><td>Regular, 1.5 line-height</td><td>Paragraphs and content</td></tr><tr><td><strong>Code</strong></td><td>Fira Mono</td><td>Code blocks and inline code</td></tr></tbody></table><h3 id="figma-design-preview" tabindex="-1">Figma Design Preview <a class="header-anchor" href="#figma-design-preview" aria-label="Permalink to &quot;Figma Design Preview&quot;">​</a></h3><p><img src="'+s+'" alt="Preview of logo"></p><p><a href="https://www.figma.com/design/DvUaZIM2Po8pyEREPgUCSq/Sci-Sync-Case-study?node-id=1-3&amp;t=6fCnJa56zdMW6Svo-1" target="_blank" rel="noreferrer">View the Figma Design Files</a></p><h2 id="scalability-strategy" tabindex="-1">Scalability Strategy <a class="header-anchor" href="#scalability-strategy" aria-label="Permalink to &quot;Scalability Strategy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Strategy</th><th>Approach</th></tr></thead><tbody><tr><td><strong>Backend</strong></td><td>Horizontal scaling</td><td>Multiple dynos with load balancer</td></tr><tr><td><strong>Database</strong></td><td>Read replicas</td><td>Separate read/write operations</td></tr><tr><td><strong>Caching</strong></td><td>Redis across instances</td><td>Shared cache for sessions</td></tr><tr><td><strong>Offline</strong></td><td>Client-side storage</td><td>Reduces server load</td></tr><tr><td><strong>USSD</strong></td><td>Africa&#39;s Talking scalability</td><td>Handles thousands of concurrent sessions</td></tr></tbody></table><hr>',135)])])}const f=e(n,[["render",d]]);export{m as __pageData,f as default};
